/*
 * Modified by Actuna Sp. z o.o.:
 *   #19: new file - supertest bound to 127.0.0.1 (a fix of flaky tests)
 *   #41: explicit errors for a TLS server, a URL given as text and http2
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

// A replacement of `require("supertest")` for tests that call `request(app)` with
// an express app (or a request handler). `agent` is not provided.
//
// supertest 6 starts a handler with `listen(0)` (all interfaces) but connects to
// 127.0.0.1:<port>. When another process on the machine holds the same port on
// 127.0.0.1 only, the request reaches that foreign server (foreign 401/404 or HTML,
// "Parse Error", "socket hang up"). Here the server listens on 127.0.0.1 only, so
// the port is always the one the request is sent to.
//
// Only plain http is supported. A TLS server, a URL given as text and http2 are
// rejected with a TypeError instead of being silently sent over plain http (or,
// for a URL, not bound to the loopback at all), which would make a test pass or
// fail for the wrong reason.

const http = require("http");
const net = require("net");
const tls = require("tls");
const supertest = require("supertest");

// net.Server#listen(port, host) resolves the host asynchronously, so unlike
// listen(port) the address is not known right after the call. The request
// is therefore sent when the server reports that it is listening.
class LoopbackTest extends supertest.Test {
    // called by the constructor of supertest.Test; the url is set in end()
    serverAddress(app, path) {
        this._loopbackApp = app;
        this._loopbackPath = path;
        return path;
    }

    end(fn) {
        const app = this._loopbackApp;
        const send = () => {
            this.url = "http://127.0.0.1:" + app.address().port + this._loopbackPath;
            super.end(fn);
        };
        if (app.address()) {
            send();
        } else {
            this._server = app; // closed by supertest.Test#end after the response
            const failed = err => fn ? fn(err) : this.emit("error", err);
            app.once("error", failed);
            app.once("listening", () => {
                app.removeListener("error", failed);
                send();
            });
            app.listen(0, "127.0.0.1");
        }
        return this;
    }
}

function checkSupported(app, options) {
    if (options && options.http2) {
        throw new TypeError("nr-test-utils/supertest: http2 is not supported, only plain http on 127.0.0.1");
    }
    if (typeof app === "string") {
        throw new TypeError("nr-test-utils/supertest: a URL given as text is not supported, pass an express app, a request handler or an http.Server");
    }
    // https.Server and http2.Http2SecureServer both extend tls.Server
    if (app instanceof tls.Server) {
        throw new TypeError("nr-test-utils/supertest: a TLS server is not supported, only plain http on 127.0.0.1");
    }
    // http2.Http2Server is a net.Server which is not an http.Server
    if (typeof app !== "function" && !(app instanceof http.Server)) {
        const what = app instanceof net.Server ? "a net.Server which is not an http.Server (http2?)" : typeof app;
        throw new TypeError("nr-test-utils/supertest: unsupported application: " + what + ", pass an express app, a request handler or an http.Server");
    }
}

function request(app, options) {
    checkSupported(app, options);
    const server = typeof app === "function" ? http.createServer(app) : app;
    const obj = {};
    http.METHODS.map(method => method.toLowerCase()).forEach(method => {
        obj[method] = url => new LoopbackTest(server, method, url);
    });
    obj.del = obj.delete;
    return obj;
}

module.exports = request;
